import { FC, HTMLAttributes, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex } from 'antd';
import cn from 'classnames';

import { PlannerDayLine, PlannerPost, usePlannerDates } from 'features/Planner';
import { dateToLocaleString, formatDate } from 'shared/utils';

import styles from './PlannerDay.module.scss';

interface IPlannerDayProps extends HTMLAttributes<HTMLDivElement> {
	posts: PlannerPost[];
	selectedDate?: Date;
	isHistory?: boolean;
}

export const PlannerDay: FC<IPlannerDayProps> = ({ className, posts, selectedDate, isHistory, ...props }) => {
	const { t } = useTranslation();
	const dates = usePlannerDates();

	if (!selectedDate) {
		selectedDate = dates.selectedDate;
	}

	const postsMap = posts.reduce(
		(acc, post) => {
			const time = formatDate(new Date(post.published_at), 'shortTime') || '';
			acc[time] = [...(acc[time] || []), post];

			return acc;
		},
		{} as Record<string, PlannerPost[]>,
	);

	const [currentTime, setCurrentTime] = useState<string>(formatDate(new Date(), 'shortTime') || '');

	useEffect(() => {
		const interval = setInterval(() => {
			setCurrentTime(formatDate(new Date(), 'shortTime') || '');
		}, 1000);

		return () => clearInterval(interval);
	}, []);

	const postsMapWithCurrentTime =
		Object.keys(postsMap)?.length > 0
			? postsMap
			: { '09:00': [], '11:00': [], '13:00': [], '15:00': [], '17:00': [], '19:00': [], '21:00': [], '23:00': [] };

	if (
		!postsMapWithCurrentTime[currentTime] &&
		selectedDate.toLocaleDateString() === new Date().toLocaleDateString() &&
		!isHistory
	) {
		postsMapWithCurrentTime[currentTime] = [];
	}

	const today = formatDate(new Date(), 'short');
	const yesterday = formatDate(new Date(new Date().setDate(new Date().getDate() - 1)), 'short');
	const isToday = formatDate(selectedDate, 'short') === today;
	const isYesterday = formatDate(selectedDate, 'short') === yesterday;

	return (
		<div {...props} className={cn(styles.plannerDay, className)}>
			<Flex gap={10} className={styles.date}>
				<Flex align="center" justify="center" className={styles.separator}>
					<div className={styles.line}></div>
					<div className={styles.dot}></div>
				</Flex>
				<div className={styles.day}>
					{isHistory && isToday && `${t('Сегодня')} • `}
					{isHistory && isYesterday && `${t('Вчера')} • `}
					{isHistory && `${formatDate(selectedDate, 'weekday')?.toUpperCase()} • `}
					{isHistory && dateToLocaleString(selectedDate, { day: '2-digit', month: 'short', year: 'numeric' })}
					{!isHistory && dateToLocaleString(selectedDate, { day: '2-digit', month: 'long' })}
				</div>
			</Flex>
			{Object.keys(postsMapWithCurrentTime)
				.sort()
				.map((time) => {
					return <PlannerDayLine key={time} time={time} posts={postsMapWithCurrentTime[time]} />;
				})}
		</div>
	);
};
