import { FC, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router-dom';

import { Badge, Button, Flex, FlexProps, Typography } from 'antd';
import { RcFile } from 'antd/es/upload';
import cn from 'classnames';
import dayjs from 'dayjs';

import CrossIcon from 'assets/images/icons/cross.svg?react';
import { useBrandSlice, useLazyOffersRetrieveQuery } from 'entities/Brand';
import { OfferCardSection } from 'entities/Offer';
import { usePostSlice } from 'entities/Post';
import { DeletePlannerPostModal, PlannerPost } from 'features/Planner';
import { EMainRoutes } from 'shared/typings';
import { OverlayLoader } from 'shared/ui';

import styles from './PlannerDayPost.module.scss';

interface IPlannerDayPostProps extends FlexProps {
	post: PlannerPost;
}

export const PlannerDayPost: FC<IPlannerDayPostProps> = ({ className, post, ...props }) => {
	const { t } = useTranslation();
	//const paymentModel = EPaymentModel.CPA; //TODO: get from api
	//const isPublished = post.channels?.some((channel) => channel.published_at);
	const [isPublished, setIsPublished] = useState(new Date(post.published_at) < new Date());

	useEffect(() => {
		const interval = setInterval(() => {
			setIsPublished(new Date(post.published_at) < new Date());
		}, 1000);

		return () => clearInterval(interval);
	}, []); //eslint-disable-line react-hooks/exhaustive-deps

	const [isDeleting, setIsDeleting] = useState(false);
	const [imagesIsLoading, setImagesIsLoading] = useState(false);
	const { setIsOpenDetailsPopup, setOffer, setVisitedOffer, visitedOffers } = useBrandSlice();
	const { setFormState, addImage } = usePostSlice();
	//const [getOffer, { data: offerDetails, isSuccess, isLoading }] = useLazyOffersRetrieveQuery();
	const [, { data: offerDetails, isSuccess, isLoading }] = useLazyOffersRetrieveQuery();
	const navigate = useNavigate();
	const { offer } = post;

	useEffect(() => {
		if (isSuccess) {
			setOffer(offerDetails);
			setVisitedOffer(offerDetails.uuid);
			setIsOpenDetailsPopup(true);
		}
	}, [isSuccess]); // eslint-disable-line react-hooks/exhaustive-deps

	const downloadImage = async (image: string) => {
		const response = await fetch(image);
		const blob = await response.blob();
		const fileReader = new FileReader();

		fileReader.addEventListener('load', () => {
			const name = image.split('/').pop();

			addImage({
				originFileObj: new File([blob], name || '') as unknown as RcFile,
				uid: Math.random().toString(36).substring(2, 15),
				name: name || '',
				preview: fileReader.result as string,
			});
		});

		fileReader.readAsDataURL(blob);
	};

	const onReschedule = async (isEdit: boolean) => {
		setFormState({
			channel_ids: post.channels?.[0]?.id || null,
			date: isEdit ? dayjs(post.published_at).set('second', 1) : null,
			time: isEdit ? dayjs(post.published_at).set('second', 1) : null,
			auto_deletion_after: post.auto_deletion_after,
			publishNow: false,
			content: post.content,
			images: [],
			published_at: post.published_at,
		});

		setImagesIsLoading(true);
		await Promise.all(post.images.map(downloadImage));
		setImagesIsLoading(false);

		navigate(
			isEdit
				? `/${EMainRoutes.POST}/${EMainRoutes.EDIT}/${post.id}?offerId=${post.offer.id}`
				: `/${EMainRoutes.POST}/${EMainRoutes.CREATE}?offerId=${post.offer.id}`,
		);
	};

	return (
		<Flex
			{...props}
			vertical
			className={cn(className, styles.card)}
			//onClick={() => getOffer(offer.id)}
		>
			{isLoading && <OverlayLoader />}
			<Flex align="start">
				<img className={styles.image} src={offer.image} alt={offer.name} />

				<Flex vertical gap={4} className={styles.info}>
					<Typography.Paragraph
						className={styles.title}
						style={{ margin: 0 }}
						strong
						type={visitedOffers.includes(offer.id) ? 'secondary' : undefined}
						ellipsis={{
							rows: 3,
						}}>
						{offer.name}
					</Typography.Paragraph>

					{/*<Flex gap={4}>
						<Tag color={EPaymentModelMap[paymentModel].color}>{EPaymentModelMap[paymentModel].text}</Tag>
					</Flex>*/}
				</Flex>
			</Flex>

			<OfferCardSection>
				<Flex gap={4} justify={'space-between'}>
					{isPublished ? (
						<Badge status="success" text={t('Опубликовано')} />
					) : (
						<Badge status="processing" text={t('Опубликуется')} />
					)}
					<Flex gap={4} align="center">
						<Typography.Text type="secondary" style={{ fontSize: 12 }}>
							{new Date(post.published_at || '').toLocaleString('ru-RU', { hour: '2-digit', minute: '2-digit' })}
						</Typography.Text>
						<Typography.Text type="secondary" style={{ fontSize: 12 }}>
							•
						</Typography.Text>
						<Typography.Text type="secondary" style={{ fontSize: 12 }}>
							{new Date(post.published_at || '').toLocaleString('ru-RU', { day: '2-digit', month: 'short' })}
						</Typography.Text>
					</Flex>
				</Flex>
			</OfferCardSection>

			<OfferCardSection padding={8}>
				{!isPublished && (
					<Flex gap={4}>
						<Button
							onClick={() => setIsDeleting(true)}
							variant="outlined"
							color="danger"
							size="large"
							icon={<CrossIcon />}
							style={{ flexShrink: 0 }}
						/>

						<Button
							onClick={() => onReschedule(true)}
							size="large"
							className={styles.button}
							block
							disabled={imagesIsLoading}
							loading={imagesIsLoading}>
							{t('Редактировать')}
						</Button>
					</Flex>
				)}

				{isPublished && (
					<Button
						onClick={() => onReschedule(false)}
						size="large"
						className={styles.button}
						block
						disabled={imagesIsLoading}
						loading={imagesIsLoading}>
						{t('Запланировать повторно')}
					</Button>
				)}
			</OfferCardSection>

			<DeletePlannerPostModal post={post} open={isDeleting} onCancel={() => setIsDeleting(false)} />
		</Flex>
	);
};
