import { FC } from 'react';

import { FlexProps } from 'antd';
import cn from 'classnames';

import styles from './OfferCardSection.module.scss';

interface IOfferCardSectionProps extends FlexProps {
	padding?: number;
}

export const OfferCardSection: FC<IOfferCardSectionProps> = ({ className, children, padding = 4, ...props }) => {
	return (
		<div {...props} style={{ padding: `${padding}px 8px` }} className={cn(className, styles.section)}>
			{children}
		</div>
	);
};
